window.GUIDE_IDX=[{"s":"creatine","c":"sport","t":{"uk":"Креатин: що це, як працює і як приймати","ru":"Креатин: что это, как работает и как принимать"},"l":{"uk":"Креатин — одна з найбільш досліджених спортивних добавок. Він допомагає м’язам швидше відновлювати енергію під час коротких потужних навантажень. Розбираємо, звідки він береться в організмі, кому підходить і на що звернути увагу під час прийому.","ru":"Креатин — одна из самых изученных спортивных добавок. Он помогает мышцам быстрее восполнять энергию при коротких мощных нагрузках. Разбираем, откуда он берётся в организме, кому подходит и на что обратить внимание при приёме."},"p":["sport-28","sport-29","sport-30","sport-34","sport-31","sport-32","sport-33","sport-53","aldous-creatina-monoidrato","aldous-creatina-monoidrato-in-caramelle-gommose","aldous-creatina-monoidrato-200-mesh-in-polvere","aldous-creatina-monoidrato-500-mesh-in-polvere"]},{"s":"creatine-hcl","c":"sport","t":{"uk":"Креатин HCl: чим відрізняється від моногідрату","ru":"Креатин HCl: чем отличается от моногидрата"},"l":{"uk":"Креатин гідрохлорид — форма, у якій молекула креатину пов’язана з соляною кислотою. Вона добре розчиняється у воді й приймається в невеликих дозах. Розповідаємо, у чому суть цієї форми, кому вона може підійти та чого від неї очікувати.","ru":"Креатин гидрохлорид — форма, в которой молекула креатина связана с соляной кислотой. Она хорошо растворяется в воде и принимается в небольших дозах. Рассказываем, в чём суть этой формы, кому она может подойти и чего от неё ожидать."},"p":["sport-27","sport-hcl-240"]},{"s":"kre-alkalyn","c":"sport","t":{"uk":"Лужний креатин Kre-Alkalyn: що це і чим відрізняється","ru":"Щелочной креатин Kre-Alkalyn: что это и чем отличается"},"l":{"uk":"Лужний (буферизований) креатин — форма креатину, яку стабілізують так, щоб він менше руйнувався в кислому середовищі шлунка. Розбираємо ідею, заявлені переваги й те, що насправді відомо про такий креатин.","ru":"Щелочной (буферизованный) креатин — форма креатина, которую стабилизируют так, чтобы он меньше разрушался в кислой среде желудка. Разбираем идею, заявленные преимущества и то, что на самом деле известно о таком креатине."},"p":["sport-45"]},{"s":"creapure","c":"sport","t":{"uk":"Creapure чи звичайний моногідрат: що обрати","ru":"Creapure или обычный моногидрат: что выбрать"},"l":{"uk":"Креатин моногідрат буває різної якості сировини. Особлива очищена форма з контрольованою чистотою вирізняється серед звичайних варіантів. Пояснюємо, чим вони різняться і коли різниця справді важлива.","ru":"Креатин моногидрат бывает разного качества сырья. Особая очищенная форма с контролируемой чистотой выделяется среди обычных вариантов. Объясняем, чем они различаются и когда разница действительно важна."},"p":["sport-23","sport-24","sport-25","sport-26","sport-28"]},{"s":"glutamine","c":"sport","t":{"uk":"Глутамін: що це, користь, дозування та застосування в спорті","ru":"Глютамин: что это, польза, дозировка и применение в спорте"},"l":{"uk":"Глутамін — найпоширеніша вільна амінокислота в організмі. Її використовують м’язи, імунні клітини та кишечник. Розбираємо, навіщо її приймають спортсмени, що підтверджено дослідженнями та як використовувати безпечно.","ru":"Глютамин — самая распространённая свободная аминокислота в организме. Её используют мышцы, иммунные клетки и кишечник. Разбираем, зачем её принимают спортсмены, что подтверждено исследованиями и как использовать безопасно."},"p":["sport-42","sport-43","sport-44","sport-49"]},{"s":"beta-alanine","c":"sport","t":{"uk":"Бета-аланін: як працює, дозування і що відчувається під час прийому","ru":"Бета-аланин: как работает, дозировка и что чувствуется при приёме"},"l":{"uk":"Бета-аланін допомагає організму виробляти карнозин — речовину, що підтримує м’язи під час інтенсивних навантажень середньої тривалості. Розповідаємо, для кого він підходить, як його приймати та чому під час прийому іноді виникає поколювання.","ru":"Бета-аланин помогает организму вырабатывать карнозин — вещество, которое поддерживает мышцы при интенсивных нагрузках средней продолжительности. Рассказываем, для кого он подходит, как его принимать и почему при приёме иногда возникает покалывание."},"p":["sport-15"]},{"s":"maltodextrin","c":"sport","t":{"uk":"Мальтодекстрин: що це і коли його приймають у спорті","ru":"Мальтодекстрин: что это и когда его принимают в спорте"},"l":{"uk":"Мальтодекстрин — швидке джерело вуглеводів у вигляді порошку без вираженого солодкого смаку. Його використовують за тривалих навантажень, коли потрібно підтримувати енергію. Розберемо, як він улаштований і в яких випадках стане в пригоді.","ru":"Мальтодекстрин — быстрый источник углеводов в виде порошка без выраженного сладкого вкуса. Его используют при длительных нагрузках, когда нужно поддерживать энергию. Разберём, как он устроен и в каких случаях пригодится."},"p":["sport-50"]},{"s":"cyclic-dextrin","c":"sport","t":{"uk":"Циклічні декстрини (Cluster Dextrin): що це і для чого потрібні","ru":"Циклические декстрины (Cluster Dextrin): что это и для чего нужны"},"l":{"uk":"Циклічні декстрини — особлива вуглеводна добавка, що швидко залишає шлунок і м’яко впливає на травлення. Її обирають для інтенсивних і тривалих навантажень. Пояснюємо, чим вона відрізняється від звичайних вуглеводів.","ru":"Циклические декстрины — особая углеводная добавка, которая быстро покидает желудок и мягко влияет на пищеварение. Её выбирают для интенсивных и длительных нагрузок. Объясняем, чем она отличается от обычных углеводов."},"p":["sport-18"]},{"s":"bcaa-211","c":"sport","t":{"uk":"BCAA 2:1:1: чому це найбільш вивчене співвідношення","ru":"BCAA 2:1:1: почему это самое изученное соотношение"},"l":{"uk":"Класичне співвідношення лейцину, ізолейцину та валіну 2:1:1 трапляється найчастіше. Розбираємо, звідки воно взялося, навіщо потрібні всі три амінокислоти та для кого така формула підходить краще.","ru":"Классическое соотношение лейцина, изолейцина и валина 2:1:1 встречается чаще всего. Разбираем, откуда оно взялось, зачем нужны все три аминокислоты и для кого такая формула подходит лучше."},"p":["sport-4","sport-5","sport-12","sport-13"]},{"s":"bcaa-sport","c":"sport","t":{"uk":"BCAA в спорті: що це за амінокислоти і для чого їх приймають","ru":"BCAA в спорте: что это за аминокислоты и для чего их принимают"},"l":{"uk":"BCAA — це три амінокислоти з розгалуженим ланцюгом: лейцин, ізолейцин і валін. Вони входять до складу м’язових білків і особливо цікаві тим, хто тренується регулярно. Розбираємо, як вони діють, які співвідношення бувають і як обрати підходяще.","ru":"BCAA — это три аминокислоты с разветвлённой цепью: лейцин, изолейцин и валин. Они входят в состав мышечных белков и особенно интересны тем, кто тренируется регулярно. Разбираем, как они действуют, какие соотношения бывают и как выбрать подходящее."},"p":["sport-4","sport-5","sport-12","sport-6","sport-7","sport-11","sport-8","sport-9","sport-10","sport-13","sport-14"]},{"s":"eaa","c":"sport","t":{"uk":"Незамінні амінокислоти EAA: для чого вони потрібні","ru":"Незаменимые аминокислоты EAA: для чего они нужны"},"l":{"uk":"EAA — повний набір із дев’яти незамінних амінокислот, які організм не може створити сам. Розбираємо, чим вони відрізняються від BCAA, навіщо потрібні разом і коли така добавка доречна.","ru":"EAA — полный набор из девяти незаменимых аминокислот, которые организм не может создать сам. Разбираем, чем они отличаются от BCAA, зачем нужны вместе и когда такая добавка уместна."},"p":["sport-35","sport-36","sport-37","sport-38","sport-39"]},{"s":"taurine","c":"sport","t":{"uk":"Таурин: що це, для чого потрібен і як приймати","ru":"Таурин: что это, для чего нужен и как принимать"},"l":{"uk":"Таурин — одна з найпоширеніших амінокислотоподібних молекул в організмі. Він присутній у серці, м’язах, сітківці ока та нервовій тканині. Розповідаємо, яку роль він відіграє, звідки надходить і кому може знадобитися добавка.","ru":"Таурин — одна из самых распространённых аминокислотоподобных молекул в организме. Он присутствует в сердце, мышцах, сетчатке глаза и нервной ткани. Рассказываем, какую роль он играет, откуда поступает и кому может пригодиться добавка."},"p":["sport-52"]},{"s":"caffeine","c":"sport","t":{"uk":"Кофеїн безводний і спорт: ефекти, дозування, коли приймати","ru":"Кофеин безводный и спорт: эффекты, дозировка, когда принимать"},"l":{"uk":"Кофеїн — одна з найбільш досліджених і доступних добавок для підвищення бадьорості та працездатності. Розбираємо, як він діє, які дози вважаються безпечними і чому важливо враховувати загальний обсяг кофеїну за день.","ru":"Кофеин — одна из самых изученных и доступных добавок для повышения бодрости и работоспособности. Разбираем, как он действует, какие дозы считаются безопасными и почему важно учитывать общий объём кофеина за день."},"p":["sport-16"]},{"s":"citrulline","c":"sport","t":{"uk":"Цитрулін: що це, для чого потрібен і як приймати","ru":"Цитруллин: что это, для чего нужен и как принимать"},"l":{"uk":"Цитрулін — амінокислота, яка бере участь в утворенні оксиду азоту й допомагає підтримувати нормальний кровотік. Її обирають спортсмени, а також люди, які цікавляться здоров’ям судин. Пояснюємо, як вона діє і в яких формах буває.","ru":"Цитруллин — аминокислота, которая участвует в образовании оксида азота и помогает поддерживать нормальный кровоток. Её выбирают спортсмены, а также люди, интересующиеся здоровьем сосудов. Объясняем, как она действует и в каких формах бывает."},"p":["sport-19","sport-21","sport-20"]},{"s":"arginine-citrulline","c":"sport","t":{"uk":"Аргінін із цитруліном: навіщо приймати їх разом","ru":"Аргинин с цитруллином: зачем принимать их вместе"},"l":{"uk":"Аргінін і цитрулін пов’язані спільним шляхом: з них в організмі утворюється оксид азоту. Комбінація цих двох амінокислот популярна серед тих, хто хоче підтримати кровотік під час тренувань. Пояснюємо логіку та правила прийому.","ru":"Аргинин и цитруллин связаны общим путём: из них в организме образуется оксид азота. Комбинация этих двух аминокислот популярна среди тех, кто хочет поддержать кровоток во время тренировок. Объясняем логику и правила приёма."},"p":["sport-47"]},{"s":"aakg","c":"sport","t":{"uk":"Аргінін AAKG: механізм дії та використання в спорті","ru":"Аргинин AAKG: механизм действия и использование в спорте"},"l":{"uk":"AAKG — це аргінін, пов’язаний з альфа-кетоглутаровою кислотою. Цю форму застосовують у передтренувальних продуктах для «памп-ефекту». Розбираємо, як вона влаштована, що відомо про її дію та як приймати.","ru":"AAKG — это аргинин, связанный с альфа-кетоглутаровой кислотой. Эту форму применяют в предтренировочных продуктах для «памп-эффекта». Разбираем, как она устроена, что известно о её действии и как принимать."},"p":["sport-1","sport-48"]},{"s":"acetyl-carnitine","c":"sport","t":{"uk":"Ацетил-L-карнітин: що це і як застосовують у спорті","ru":"Ацетил-L-карнитин: что это и как применяют в спорте"},"l":{"uk":"Ацетил-L-карнітин — форма карнітину, яка добре проникає в нервові клітини й мозок. Її застосовують для підтримки енергообміну та концентрації. Розповідаємо, чим вона відрізняється від інших форм карнітину й кому підходить.","ru":"Ацетил-L-карнитин — форма карнитина, которая хорошо проникает в нервные клетки и мозг. Её применяют для поддержки энергообмена и концентрации. Рассказываем, чем она отличается от других форм карнитина и кому подходит."},"p":["sport-2","sport-3"]},{"s":"carnitine-diet","c":"sport","t":{"uk":"L-карнітин і дієта: що це, як діє та реалістичні очікування","ru":"L-карнитин и диета: что это, как действует и реалистичные ожидания"},"l":{"uk":"L-карнітин часто називають «жироспалювачем», але насправді його роль тонша: він допомагає клітині використовувати жири як джерело енергії. Розбираємо, що відомо про його дію, кому він може стати в пригоді та як приймати.","ru":"L-карнитин часто называют «жиросжигателем», но на самом деле его роль тоньше: он помогает клетке использовать жиры как источник энергии. Разбираем, что известно о его действии, кому он может пригодиться и как принимать."},"p":["sport-17","sport-46","aldous-l-carnitina"]},{"s":"carnitine-heart","c":"sport","t":{"uk":"L-карнітин і серце: роль ТМАО та кишкової мікробіоти","ru":"L-карнитин и сердце: роль ТМАО и кишечной микробиоты"},"l":{"uk":"Навколо карнітину триває наукова дискусія: чи може він підвищувати рівень речовини ТМАО, пов’язаної з ризиками для судин. Пояснюємо простими словами, що це за речовина, до чого тут кишкові бактерії та що врахувати під час прийому.","ru":"Вокруг карнитина идёт научная дискуссия: может ли он повышать уровень вещества ТМАО, связанного с рисками для сосудов. Объясняем простыми словами, что это за вещество, при чём здесь кишечные бактерии и что учесть при приёме."},"p":["sport-17","sport-46"]},{"s":"energy-express","c":"sport","t":{"uk":"Електроліти та вуглеводи: як підтримувати енергію та гідратацію під час навантаження","ru":"Электролиты и углеводы: как поддерживать энергию и гидратацию во время нагрузки"},"l":{"uk":"Під час довгих тренувань організм втрачає не лише енергію, а й воду з мінеральними солями. Напій з вуглеводами та електролітами допомагає підтримувати обидва баланси. Пояснюємо, як він улаштований і коли потрібен.","ru":"Во время долгих тренировок организм теряет не только энергию, но и воду с минеральными солями. Напиток с углеводами и электролитами помогает поддерживать оба баланса. Объясняем, как он устроен и когда нужен."},"p":["sport-40"]},{"s":"glycine","c":"sport","t":{"uk":"Гліцин: для чого потрібен, де міститься і як діє на нервову систему","ru":"Глицин: для чего нужен, где содержится и как действует на нервную систему"},"l":{"uk":"Гліцин — найпростіша амінокислота, але роль у неї велика: вона входить до складу колагену, бере участь у роботі нервової системи та підтримує якість сну. Розповідаємо, де вона трапляється, як діє і кому може стати в пригоді добавка.","ru":"Глицин — самая простая аминокислота, но роль у неё большая: она входит в состав коллагена, участвует в работе нервной системы и поддерживает качество сна. Рассказываем, где она встречается, как действует и кому может пригодиться добавка."},"p":["sport-41"]},{"s":"cla","c":"weight","t":{"uk":"CLA — кон’югована лінолева кислота: як працює і чого очікувати","ru":"CLA — конъюгированная линолевая кислота: как работает и чего ждать"},"l":{"uk":"CLA — це група жирних кислот, які природно містяться в м’ясі та молочних продуктах жуйних тварин. Їх обирають під час контролю ваги. Розбираємо, що відомо про їхню дію й які очікування реалістичні.","ru":"CLA — это группа жирных кислот, которые естественным образом содержатся в мясе и молочных продуктах жвачных животных. Их выбирают при контроле веса. Разбираем, что известно об их действии и какие ожидания реалистичны."},"p":["sport-22"]},{"s":"zma","c":"min","t":{"uk":"Цинк і магній (ZMA): навіщо вони потрібні спортсмену та як приймати","ru":"Цинк и магний (ZMA): зачем они нужны спортсмену и как принимать"},"l":{"uk":"Цинк і магній — два мінерали, які беруть участь у роботі м’язів, нервової системи та обміні речовин. Їх часто приймають разом, особливо за регулярних тренувань. Розбираємо роль кожного та правила прийому.","ru":"Цинк и магний — два минерала, которые участвуют в работе мышц, нервной системы и обмене веществ. Их часто принимают вместе, особенно при регулярных тренировках. Разбираем роль каждого и правила приёма."},"p":["sport-54","sport-55"]},{"s":"folic-acid","c":"vit","t":{"uk":"Фолієва кислота (вітамін B9): для чого потрібна і де міститься","ru":"Фолиевая кислота (витамин B9): для чего нужна и где содержится"},"l":{"uk":"Фолієва кислота — водорозчинний вітамін групи B, необхідний для поділу клітин та утворення крові. Особливо важлива вона під час планування вагітності. Розповідаємо, чим фолієва кислота відрізняється від фолатів у продуктах, скільки потрібно і коли добавка доречна.","ru":"Фолиевая кислота — водорастворимый витамин группы B, необходимый для деления клеток и образования крови. Особенно важна она при планировании беременности. Рассказываем, чем фолиевая кислота отличается от фолатов в продуктах, сколько нужно и когда добавка уместна."},"p":["acido-folico-365-compresse","vitamina-b12-acido-folico-vitamina-c-400-compresse"]},{"s":"vitamin-e","c":"vit","t":{"uk":"Вітамін E: що це, користь, джерела та дозування","ru":"Витамин E: что это, польза, источники и дозировка"},"l":{"uk":"Вітамін E — жиророзчинний антиоксидант, який захищає клітинні мембрани від окиснювального пошкодження. Розповідаємо, де він міститься, чим відрізняються його форми, скільки потрібно і коли добавка доречна.","ru":"Витамин E — жирорастворимый антиоксидант, который защищает клеточные мембраны от окислительного повреждения. Рассказываем, где он содержится, чем отличаются его формы, сколько нужно и когда добавка уместна."},"p":["vitamina-e-360-compresse"]},{"s":"beta-carotene","c":"vit","t":{"uk":"Бета-каротин: що це, роль в організмі та кому підходить","ru":"Бета-каротин: что это, роль в организме и кому подходит"},"l":{"uk":"Бета-каротин — природний пігмент, що надає яскравого кольору моркві та гарбузу. Організм перетворює його на вітамін A за потреби. Розповідаємо, чим він відрізняється від «готового» вітаміну A, кому підходить і на що звернути увагу.","ru":"Бета-каротин — природный пигмент, придающий яркий цвет моркови и тыкве. Организм превращает его в витамин A по мере необходимости. Рассказываем, чем он отличается от «готового» витамина A, кому подходит и на что обратить внимание."},"p":["beta-carotene-180-compresse","philautia-1"]},{"s":"vitamin-a","c":"vit","t":{"uk":"Вітамін A та ретинол: користь, джерела та ознаки нестачі","ru":"Витамин A и ретинол: польза, источники и признаки нехватки"},"l":{"uk":"Вітамін A потрібен для зору, шкіри, слизових та імунітету. Це жиророзчинний вітамін: він накопичується в печінці, тому важливо дотримуватися дозування. Розповідаємо, де він міститься, як проявляється нестача та чому надлишок небезпечний.","ru":"Витамин A нужен для зрения, кожи, слизистых и иммунитета. Это жирорастворимый витамин: он накапливается в печени, поэтому важно соблюдать дозировку. Рассказываем, где он содержится, как проявляется нехватка и почему избыток опасен."},"p":["vitamina-a-365-compresse","vitamina-a-4000-ui-400-compresse"]},{"s":"vitamin-b12","c":"vit","t":{"uk":"Вітамін B12: користь, джерела, ознаки нестачі та форми","ru":"Витамин B12: польза, источники, признаки нехватки и формы"},"l":{"uk":"Вітамін B12 (кобаламін) потрібен для крові, нервової системи та енергії. Він міститься майже лише в продуктах тваринного походження, тому особливо важливий вегетаріанцям і веганам. Розбираємо форми вітаміну та правила прийому.","ru":"Витамин B12 (кобаламин) нужен для крови, нервной системы и энергии. Он содержится почти только в продуктах животного происхождения, поэтому особенно важен вегетарианцам и веганам. Разбираем формы витамина и правила приёма."},"p":["vitamina-b12-450-compresse","vitamina-b12-acido-folico-vitamina-c-400-compresse","vitamina-b12-sublinguale-120-compresse","vitamina-b12-vegan","aldous-vitamina-b12-con-acido-folico"]},{"s":"b-vitamins","c":"vit","t":{"uk":"Вітаміни групи B та фізична працездатність","ru":"Витамины группы B и физическая работоспособность"},"l":{"uk":"Вісім вітамінів групи B працюють як єдина команда: вони допомагають перетворювати їжу на енергію, підтримують нервову систему та кровотворення. Розповідаємо, навіщо вони потрібні за тренувань і коли комплекс доречний.","ru":"Восемь витаминов группы B работают как единая команда: они помогают превращать пищу в энергию, поддерживают нервную систему и кроветворение. Рассказываем, зачем они нужны при тренировках и когда комплекс уместен."},"p":["complesso-vitamina-b-365-compresse","aldous-vitamina-b-complex-con-vitamina-c"]},{"s":"vitamin-c-zinc","c":"vit","t":{"uk":"Вітамін C із цинком: як працює тандем для імунітету","ru":"Витамин C с цинком: как работает тандем для иммунитета"},"l":{"uk":"Вітамін C і цинк — дві речовини, які беруть участь у роботі імунної системи й доповнюють одна одну. Розповідаємо, навіщо їх об’єднують, кому підійде така комбінація та як приймати її безпечно.","ru":"Витамин C и цинк — два вещества, которые участвуют в работе иммунной системы и дополняют друг друга. Рассказываем, зачем их объединяют, кому подойдёт такая комбинация и как принимать её безопасно."},"p":["vitamina-c-con-zinco-210-compresse","aldous-vitamina-c-con-zinco-e-coenzima-q10"]},{"s":"vitamin-c","c":"vit","t":{"uk":"Вітамін C: роль в організмі, джерела та як приймати","ru":"Витамин C: роль в организме, источники и как принимать"},"l":{"uk":"Вітамін C (аскорбінова кислота) — один із найвідоміших вітамінів. Він потрібен для імунітету, шкіри, судин і засвоєння заліза. Організм не виробляє й не запасає його, тому він має надходити щодня. Розповідаємо, скільки його потрібно і як приймати добавку.","ru":"Витамин C (аскорбиновая кислота) — один из самых известных витаминов. Он нужен для иммунитета, кожи, сосудов и усвоения железа. Организм не вырабатывает и не запасает его, поэтому он должен поступать ежедневно. Рассказываем, сколько его нужно и как принимать добавку."},"p":["vitamina-c-200-compresse","vitamina-c-con-zinco-210-compresse","aldous-vitamina-c-pura"]},{"s":"vitamin-d3","c":"vit","t":{"uk":"Вітамін D3: користь, дозування та джерела","ru":"Витамин D3: польза, дозировка и источники"},"l":{"uk":"Вітамін D3 виробляється в шкірі під дією сонця й необхідний кісткам, м’язам та імунітету. У північних широтах його часто не вистачає. Розповідаємо, де він міститься, скільки потрібно та як приймати добавку безпечно.","ru":"Витамин D3 вырабатывается в коже под действием солнца и необходим костям, мышцам и иммунитету. В северных широтах его часто не хватает. Рассказываем, где он содержится, сколько нужно и как принимать добавку безопасно."},"p":["vitamina-d-200-compresse","vitamina-d-365-capsule","vitamina-d3-2000-400-compresse","vitamina-d3-gocce-30-ml"]},{"s":"vitamin-d-deficiency","c":"vit","t":{"uk":"Дефіцит вітаміну D: причини, ознаки та як його поповнювати","ru":"Дефицит витамина D: причины, признаки и как его восполнять"},"l":{"uk":"Нестача вітаміну D — одна з найпоширеніших у північних широтах. Вона довго може не давати явних симптомів. Розбираємо, звідки береться дефіцит, на що він може вказувати, як його перевіряють і як поповнювати безпечно.","ru":"Нехватка витамина D — одна из самых распространённых в северных широтах. Она долго может не давать явных симптомов. Разбираем, откуда берётся дефицит, на что он может указывать, как его проверяют и как восполнять безопасно."},"p":["vitamina-d-200-compresse","vitamina-d-365-capsule","vitamina-d3-2000-400-compresse","vitamina-d3-e-k2-5000","vitamina-d3-gocce-30-ml"]},{"s":"d3-k2","c":"vit","t":{"uk":"Вітаміни D3 і K2 разом: навіщо потрібна пара для кісток і судин","ru":"Витамины D3 и K2 вместе: зачем нужна пара для костей и сосудов"},"l":{"uk":"Вітамін D3 допомагає засвоювати кальцій, а вітамін K2 спрямовує його в кістки. Така пара працює злагодженіше, ніж кожен вітамін окремо. Пояснюємо, як вони доповнюють одне одного і як приймати комбінацію.","ru":"Витамин D3 помогает усваивать кальций, а витамин K2 направляет его в кости. Такая пара работает слаженнее, чем каждый витамин по отдельности. Объясняем, как они дополняют друг друга и как принимать комбинацию."},"p":["vitamina-d3-e-k2-5000","vitamina-dk-compresse","aldous-d3k2-calcio-gummies"]},{"s":"vitamin-k2","c":"vit","t":{"uk":"Вітамін K2: для чого потрібен, форми та як приймати","ru":"Витамин K2: для чего нужен, формы и как принимать"},"l":{"uk":"Вітамін K2 допомагає спрямовувати кальцій у кістки й бере участь у підтриманні здоров’я судин. Він мало знайомий більшості людей, хоча відіграє важливу роль в обміні кальцію. Розповідаємо, чим він відрізняється від K1, які бувають форми та як приймати.","ru":"Витамин K2 помогает направлять кальций в кости и участвует в поддержании здоровья сосудов. Он мало знаком большинству людей, хотя играет важную роль в обмене кальция. Рассказываем, чем он отличается от K1, какие бывают формы и как принимать."},"p":["vitamina-k","vitamina-k2-mk7-gocce"]},{"s":"multivitamin","c":"vit","t":{"uk":"Мультивітаміни: що це, кому вони потрібні та як обрати","ru":"Мультивитамины: что это, кому они нужны и как выбрать"},"l":{"uk":"Мультивітамінний комплекс об’єднує в одній таблетці набір вітамінів і мінералів. Він не замінює харчування, але допомагає закрити можливі прогалини в раціоні. Розповідаємо, кому такий комплекс може стати в пригоді, на що дивитися під час вибору та як приймати.","ru":"Мультивитаминный комплекс объединяет в одной таблетке набор витаминов и минералов. Он не заменяет питание, но помогает закрыть возможные пробелы в рационе. Рассказываем, кому такой комплекс может пригодиться, на что смотреть при выборе и как принимать."},"p":["multivitaminico","aldous-multivitaminico","aldous-multivitaminico-caramelle-gommose","aldous-multivitaminico-per-bambini-caramelle-gommose"]},{"s":"biotin","c":"vit","t":{"uk":"Біотин (вітамін B7) для волосся, шкіри та нігтів","ru":"Биотин (витамин B7) для волос, кожи и ногтей"},"l":{"uk":"Біотин — водорозчинний вітамін групи B, який називають вітаміном краси. Він бере участь в обміні речовин і підтримує нормальний стан волосся та шкіри. Розповідаємо, що відомо про його користь, як приймати та чому біотин може спотворювати аналізи.","ru":"Биотин — водорастворимый витамин группы B, который называют витамином красоты. Он участвует в обмене веществ и поддерживает нормальное состояние волос и кожи. Рассказываем, что известно о его пользе, как принимать и почему биотин может искажать анализы."},"p":["biotina","philautia-2","aldous-biotina-con-zinco-selenio-vitamina-d3-e-vitamina-e","aldous-acido-ialuronico-con-collagene-biotina-vitamine-e-minerali","aldous-biotina-caramelle-gommose"]},{"s":"zinc","c":"min","t":{"uk":"Цинк: для чого потрібен, де міститься і скільки приймати","ru":"Цинк: для чего нужен, где содержится и сколько принимать"},"l":{"uk":"Цинк — незамінний мікроелемент, що входить до складу сотень ферментів. Він потрібен імунітету, шкірі, волоссю, зору та обміну речовин. Організм не запасає його наперед, тому цинк має надходити щодня. Розбираємо, де його шукати, як проявляється нестача та як приймати добавку.","ru":"Цинк — незаменимый микроэлемент, который входит в состав сотен ферментов. Он нужен иммунитету, коже, волосам, зрению и обмену веществ. Организм не запасает его впрок, поэтому цинк должен поступать каждый день. Разбираем, где его искать, как проявляется нехватка и как принимать добавку."},"p":["zinco-bisglicinato-400-compresse","zinco-in-gocce-30-ml"]},{"s":"zinc-bisglycinate","c":"min","t":{"uk":"Цинк бісгліцинат: чим ця форма відрізняється від звичайного цинку","ru":"Цинк бисглицинат: чем эта форма отличается от обычного цинка"},"l":{"uk":"Бісгліцинат цинку — хелатна форма, у якій цинк зв’язаний з амінокислотою гліцином. Її обирають за добру переносимість і засвоєння. Пояснюємо, що таке хелат, у чому плюси цієї форми та кому вона особливо підходить.","ru":"Бисглицинат цинка — хелатная форма, в которой цинк связан с аминокислотой глицином. Её выбирают за хорошую переносимость и усвоение. Объясняем, что такое хелат, в чём плюсы этой формы и кому она особенно подходит."},"p":["zinco-bisglicinato-400-compresse"]},{"s":"mg-bisglycinate","c":"min","t":{"uk":"Магній бісгліцинат: властивості, користь та особливості форми","ru":"Магний бисглицинат: свойства, польза и особенности формы"},"l":{"uk":"Бісгліцинат магнію — хелатна форма мінералу, пов’язана з гліцином. Його обирають за добре засвоєння і м’якість для шлунка. Розповідаємо, чим він відрізняється від інших форм магнію, для чого потрібен і як приймати.","ru":"Бисглицинат магния — хелатная форма минерала, связанная с глицином. Его выбирают за хорошую усвояемость и мягкость для желудка. Рассказываем, чем он отличается от других форм магния, для чего нужен и как принимать."},"p":["fortis-magnesium","magnesio-bisglicinato-180-capsule","aldous-bisglicinato-di-magnesio"]},{"s":"mg-stress","c":"min","t":{"uk":"Магній і стрес: як мінерал пов’язаний з нервовою системою","ru":"Магний и стресс: как минерал связан с нервной системой"},"l":{"uk":"Магній часто називають мінералом спокою. Він бере участь у передачі нервових імпульсів і допомагає нервовій системі справлятися з навантаженням. Розповідаємо, як стрес і магній впливають одне на одного, кому може стати в пригоді добавка і яку форму обрати.","ru":"Магний часто называют минералом спокойствия. Он участвует в передаче нервных импульсов и помогает нервной системе справляться с нагрузкой. Рассказываем, как стресс и магний влияют друг на друга, кому может пригодиться добавка и какую форму выбрать."},"p":["fortis-magnesium","magnesio","magnesio-bisglicinato-180-capsule","magnesio-citrato-240-capsule","magnesio-marino","aldous-bisglicinato-di-magnesio","aldous-citrato-di-magnesio-puro","aldous-magnesio-con-vitamina-c-b5-e-b6","aldous-magnesio-completo","aldous-magnesio-caramelle-gommose"]},{"s":"mg-menopause","c":"min","t":{"uk":"Магній у менопаузі: навіщо він потрібен і як приймати","ru":"Магний в менопаузе: зачем он нужен и как принимать"},"l":{"uk":"У період менопаузи організм жінки перебудовується: змінюється гормональний фон, обмін речовин, стан кісток і сну. Магній бере участь у багатьох із цих процесів. Розповідаємо, чому потреба в ньому може бути вищою і як правильно обрати добавку.","ru":"В период менопаузы организм женщины перестраивается: меняется гормональный фон, обмен веществ, состояние костей и сна. Магний участвует во многих из этих процессов. Рассказываем, почему потребность в нём может быть выше и как правильно выбрать добавку."},"p":["fortis-magnesium","magnesio","magnesio-bisglicinato-180-capsule","magnesio-citrato-240-capsule"]},{"s":"mg-memory","c":"min","t":{"uk":"Магній L-треонат (Magtein): магній для пам’яті та концентрації","ru":"Магний L-треонат (Magtein): магний для памяти и концентрации"},"l":{"uk":"Магній L-треонат — особлива форма мінералу, яку вивчають у зв’язку з роботою мозку. Вона розрахована на те, щоб підвищувати рівень магнію в нервовій тканині. Розповідаємо, що це за форма, що про неї відомо і кому вона може бути цікавою.","ru":"Магний L-треонат — особая форма минерала, которую изучают в связи с работой мозга. Она рассчитана на то, чтобы повышать уровень магния в нервной ткани. Рассказываем, что это за форма, что о ней известно и кому она может быть интересна."},"p":["magtein-magnesio-treonato-90-capsule"]},{"s":"mg-sleep","c":"min","t":{"uk":"Магній для сну: як він допомагає розслабитися і яку форму обрати","ru":"Магний для сна: как он помогает расслабиться и какую форму выбрать"},"l":{"uk":"Якість сну залежить від багатьох факторів, і один із них — достатня кількість магнію. Мінерал бере участь у роботі систем, які допомагають організму переходити в режим відпочинку. Розбираємо механізми, форми та правила вечірнього прийому.","ru":"Качество сна зависит от многих факторов, и один из них — достаточное количество магния. Минерал участвует в работе систем, которые помогают организму переходить в режим отдыха. Разбираем механизмы, формы и правила вечернего приёма."},"p":["fortis-magnesium","magnesio-bisglicinato-180-capsule","magnesio-taurato-120-capsule","aldous-magnesio-completo"]},{"s":"mg-constipation","c":"min","t":{"uk":"Магній за закрепів: як працює і яка форма підходить","ru":"Магний при запорах: как работает и какая форма подходит"},"l":{"uk":"Магній відомий своєю м’якою послаблювальною дією: він приваблює воду в кишечник і допомагає розм’якшити стілець. Але не будь-яка форма працює однаково. Розбираємо, як це відбувається, які форми обирати і коли потрібен лікар.","ru":"Магний известен своим мягким послабляющим действием: он привлекает воду в кишечник и помогает размягчить стул. Но не любая форма работает одинаково. Разбираем, как это происходит, какие формы выбирать и когда нужен врач."},"p":["magnesio-citrato-240-capsule","magnesio-ossido-240-capsule","ossido-di-magnesio","aldous-citrato-di-magnesio-puro"]},{"s":"ca-mg-zn","c":"min","t":{"uk":"Кальцій, магній і цинк: навіщо об’єднують три мінерали","ru":"Кальций, магний и цинк: зачем объединяют три минерала"},"l":{"uk":"Кальцій, магній і цинк працюють в організмі як одна команда: вони підтримують кістки, м’язи, нервову систему та імунітет. Пояснюємо, як вони доповнюють одне одного, кому підійде комплекс і як приймати його правильно.","ru":"Кальций, магний и цинк работают в организме как одна команда: они поддерживают кости, мышцы, нервную систему и иммунитет. Объясняем, как они дополняют друг друга, кому подойдёт комплекс и как принимать его правильно."},"p":["calcio-magnesio-zinco-400-compresse"]},{"s":"mg-malate","c":"min","t":{"uk":"Магній малат: форма магнію для енергії вдень","ru":"Магний малат: форма магния для энергии днём"},"l":{"uk":"Магній малат — сполука магнію з яблучною кислотою. Обидві частини беруть участь у виробленні енергії в клітинах, тому цю форму часто обирають для денного прийому. Розбираємося, чим вона відрізняється та кому підходить.","ru":"Магний малат — соединение магния с яблочной кислотой. Обе части участвуют в производстве энергии в клетках, поэтому эту форму часто выбирают для дневного приёма. Разбираемся, чем она отличается и кому подходит."},"p":["magnesio-malato-240-compresse"]},{"s":"selenium","c":"min","t":{"uk":"Селен: користь, джерела та безпечне дозування","ru":"Селен: польза, источники и безопасная дозировка"},"l":{"uk":"Селен — мікроелемент, якого потрібно зовсім небагато, але без якого не обходиться ні щитоподібна залоза, ні антиоксидантний захист клітин. Розбираємося, навіщо він потрібен, де його шукати в харчуванні та коли має сенс добавка.","ru":"Селен — микроэлемент, которого нужно совсем немного, но без которого не обходится ни щитовидная железа, ни антиоксидантная защита клеток. Разбираемся, для чего он нужен, где его искать в питании и когда имеет смысл добавка."},"p":["iodio-selenio","iodio-selenio-150-mcg-160-compresse","selenio-365-compresse"]},{"s":"iodine-selenium","c":"min","t":{"uk":"Йод і селен разом: підтримка щитоподібної залози","ru":"Йод и селен вместе: поддержка щитовидной железы"},"l":{"uk":"Щитоподібній залозі для нормальної роботи потрібно одразу кілька мікроелементів, і два головні з них — йод і селен. Розповідаємо, як вони взаємодіють і чому їх часто об’єднують в одному комплексі.","ru":"Щитовидной железе для нормальной работы нужны сразу несколько микроэлементов, и два главных из них — йод и селен. Рассказываем, как они взаимодействуют и почему их часто объединяют в одном комплексе."},"p":["iodio-selenio","iodio-selenio-150-mcg-160-compresse"]},{"s":"iodine","c":"min","t":{"uk":"Йод і щитоподібна залоза: кому і скільки","ru":"Йод и щитовидная железа: кому и сколько"},"l":{"uk":"Йод — незамінний мікроелемент: організм не виробляє його сам і має отримувати з їжею. Розповідаємо, навіщо він потрібен, звідки береться, як зрозуміти, що його мало, і чому надлишок також небажаний.","ru":"Йод — незаменимый микроэлемент: организм не вырабатывает его сам и должен получать с пищей. Рассказываем, зачем он нужен, откуда берётся, как понять, что его мало, и почему избыток тоже нежелателен."},"p":["iodio","iodio-150g-120-compresse","iodio-365-compresse","potassio-ioduro"]},{"s":"kelp","c":"herb","t":{"uk":"Келп і фукус: морські водорості та щитоподібна залоза","ru":"Келп и фукус: морские водоросли и щитовидная железа"},"l":{"uk":"Бурі водорості келп і фукус здавна використовуються в харчуванні та в традиційній практиці як природне джерело йоду. Розбираємося, що вони містять, кому підходять і яких запобіжних заходів варто дотримуватися.","ru":"Бурые водоросли келп и фукус давно используются в питании и в традиционной практике как природный источник йода. Разбираемся, что они содержат, кому подходят и какие меры предосторожности стоит соблюдать."},"p":["fucus","fucus-kelp-algae-150mcg-365-compresse"]},{"s":"iron","c":"min","t":{"uk":"Залізо: дефіцит, харчування та добавки","ru":"Железо: дефицит, питание и добавки"},"l":{"uk":"Залізо переносить кисень по всьому організму, тому його нестача позначається на енергії, концентрації та самопочутті. Розбираємося, через що виникає дефіцит, як його запідозрити та як правильно підходити до добавок.","ru":"Железо переносит кислород по всему организму, поэтому его нехватка отражается на энергии, концентрации и самочувствии. Разбираемся, из-за чего возникает дефицит, как его заподозрить и как правильно подходить к добавкам."},"p":["ferro-bisglicinato","aldous-bisglicinato-di-ferro-vitamina-c-acido-folico-b12"]},{"s":"chromium","c":"min","t":{"uk":"Хрому піколінат: для чого потрібен і як приймати","ru":"Хрома пиколинат: для чего нужен и как принимать"},"l":{"uk":"Хром — мікроелемент, який пов’язують з обміном вуглеводів і відчуттям контролю над апетитом. Розбираємося, що відомо про хром, кому він може підійти й чому не варто чекати від нього див.","ru":"Хром — микроэлемент, который связывают с обменом углеводов и чувством контроля над аппетитом. Разбираемся, что известно о хроме, кому он может подойти и почему не стоит ждать от него чудес."},"p":["cromo-picolinato-365-compresse"]},{"s":"fenugreek","c":"herb","t":{"uk":"Пажитник (фенугрек): користь і застосування","ru":"Пажитник (фенугрек): польза и применение"},"l":{"uk":"Пажитник — пряна рослина, відома ще з часів Стародавнього Єгипту. Його насіння використовують і на кухні, і в народній практиці. Розповімо, чим цікавий фенугрек, для чого його приймають і які нюанси потрібно знати.","ru":"Пажитник — пряное растение, известное со времён Древнего Египта. Его семена используют и на кухне, и в народной практике. Расскажем, чем интересен фенугрек, для чего его принимают и какие нюансы нужно знать."},"p":["fieno-greco-180-capsule"]},{"s":"shiitake","c":"mush","t":{"uk":"Шиітаке: цілющий гриб для імунітету","ru":"Шиитаке: целебный гриб для иммунитета"},"l":{"uk":"Шиітаке — один із найвідоміших їстівних грибів Східної Азії. Його вирощують понад тисячу років і цінують і за смак, і за склад. Розповімо, що містить шиітаке, чим він може бути корисним і як приймати його у вигляді добавки.","ru":"Шиитаке — один из самых известных съедобных грибов Восточной Азии. Его выращивают более тысячи лет и ценят и за вкус, и за состав. Расскажем, что содержит шиитаке, чем он может быть полезен и как принимать его в виде добавки."},"p":["shiitake-120-capsule"]},{"s":"lutein","c":"anti","t":{"uk":"Лютеїн і зеаксантин: захист очей від навантаження","ru":"Лютеин и зеаксантин: защита глаз от нагрузки"},"l":{"uk":"Лютеїн і зеаксантин — рослинні пігменти-каротиноїди, які накопичуються в сітківці ока. Вони фільтрують синє світло та захищають клітини від окислювального стресу. Розповідаємо, навіщо потрібні ці речовини, кому підійде добавка та як приймати.","ru":"Лютеин и зеаксантин — растительные пигменты-каротиноиды, которые накапливаются в сетчатке глаза. Они фильтруют синий свет и защищают клетки от окислительного стресса. Рассказываем, зачем нужны эти вещества, кому подойдёт добавка и как принимать."},"p":["luteina-e-zeaxantina-90-compresse"]},{"s":"green-coffee","c":"weight","t":{"uk":"Зелена кава: хлорогенова кислота та контроль ваги","ru":"Зелёный кофе: хлорогеновая кислота и контроль веса"},"l":{"uk":"Зелена кава — це необсмажені зерна кави. У них багато хлорогенової кислоти, яка під час обсмажування частково руйнується. Розповідаємо, що відомо про дію екстракту зеленої кави, чого від нього можна очікувати та які потрібні запобіжні заходи.","ru":"Зелёный кофе — это необжаренные зёрна кофе. В них много хлорогеновой кислоты, которая при обжарке частично разрушается. Рассказываем, что известно о действии экстракта зелёного кофе, чего от него можно ожидать и какие нужны меры предосторожности."},"p":["caffe-verde-90-capsule"]},{"s":"black-garlic","c":"herb","t":{"uk":"Чорний часник: чим він відрізняється від звичайного","ru":"Чёрный чеснок: чем он отличается от обычного"},"l":{"uk":"Чорний часник — це звичайний часник, який витримують за контрольованої температури та вологості протягом кількох тижнів. Він стає м’яким, солодкуватим і майже без запаху. Розповімо, чим він цікавий і кому підходить.","ru":"Чёрный чеснок — это обычный чеснок, который выдерживают при контролируемой температуре и влажности в течение нескольких недель. Он становится мягким, сладковатым и почти без запаха. Расскажем, чем он интересен и кому подходит."},"p":["aglio-nero-180-capsule"]},{"s":"pea","c":"joint","t":{"uk":"ПЕА (пальмітоїлетаноламід): що це і як працює","ru":"ПЭА (пальмитоилэтаноламид): что это и как работает"},"l":{"uk":"ПЕА — природний жирнокислотний амід, який виробляє сам організм. Її вивчають як речовину, що сприяє комфортній роботі нервової системи та нормальній відповіді на дискомфорт. Розповідаємо, що відомо про ПЕА, кому вона може підійти та як приймати.","ru":"ПЭА — природная жирная кислота-амид, которую вырабатывает сам организм. Её изучают как вещество, способствующее комфортной работе нервной системы и нормальному ответу на дискомфорт. Рассказываем, что известно о ПЭА, кому она может подойти и как принимать."},"p":["pea-120-capsule"]},{"s":"collagen-bovine","c":"joint","t":{"uk":"Колаген: бичачий чи морський, як обрати","ru":"Коллаген: бычий или морской, как выбрать"},"l":{"uk":"Колаген — головний білок сполучної тканини: він є в шкірі, суглобах, сухожилках, кістках. З віком його вироблення знижується, тому колаген популярний серед добавок. Розповідаємо, чим відрізняються бичачий і морський колаген та як їх приймати.","ru":"Коллаген — главный белок соединительной ткани: он есть в коже, суставах, сухожилиях, костях. С возрастом его выработка снижается, поэтому коллаген популярен среди добавок. Рассказываем, чем отличаются бычий и морской коллаген и как их принимать."},"p":["collagene-marino-240-compresse","philautia-4","philautia-5","philautia-6","aldous-collagene-marino-idrolizzato","aldous-acido-ialuronico-con-collagene-biotina-vitamine-e-minerali","aldous-collagene-idrolizzato-bovino-in-polvere-neutro"]},{"s":"collagen-hyaluronic","c":"joint","t":{"uk":"Колаген і гіалуронова кислота: союз для шкіри та суглобів","ru":"Коллаген и гиалуроновая кислота: союз для кожи и суставов"},"l":{"uk":"Колаген і гіалуронова кислота — дві речовини, які визначають пружність і зволоженість шкіри, а також рухливість суглобів. Розповідаємо, чим вони доповнюють одна одну та чому їх часто об’єднують в одній добавці.","ru":"Коллаген и гиалуроновая кислота — два вещества, которые определяют упругость и увлажнённость кожи, а также подвижность суставов. Рассказываем, чем они дополняют друг друга и почему их часто объединяют в одной добавке."},"p":["collagene-acido-ialuronico-120-compresse","aldous-acido-ialuronico-con-collagene-biotina-vitamine-e-minerali","aldous-collagene-caramelle-gommose","aldous-collagene-idrolizzato-con-acido-ialuronico-coenzima-q10-zinco-e-vitamine","yamamoto-exceptionhyal-jump-60-compresse"]},{"s":"flaxseed-oil","c":"omega","t":{"uk":"Лляна олія: рослинна омега-3 (ALA)","ru":"Льняное масло: растительная омега-3 (ALA)"},"l":{"uk":"Лляна олія — одне з найбагатших рослинних джерел омега-3. Її використовують вегетаріанці та всі, хто хоче урізноманітнити раціон. Розповідаємо, чим вона корисна, у чому її особливості та як приймати лляну олію в капсулах.","ru":"Льняное масло — один из самых богатых растительных источников омега-3. Его используют вегетарианцы и все, кто хочет разнообразить рацион. Рассказываем, чем оно полезно, в чём его особенности и как принимать льняное масло в капсулах."},"p":["olio-di-semi-di-lino-180-softgel"]},{"s":"hemp-oil","c":"omega","t":{"uk":"Конопляна олія: збалансоване джерело омега-3 та омега-6","ru":"Конопляное масло: сбалансированный источник омега-3 и омега-6"},"l":{"uk":"Конопляну олію отримують із насіння технічної коноплі. Її цінують за склад жирних кислот: у ній ідеальне співвідношення омега-6 та омега-3. Розповідаємо, чим вона корисна, як відрізняється від олії CBD і як приймати.","ru":"Конопляное масло получают из семян технической конопли. Его ценят за состав жирных кислот: в нём идеальное соотношение омега-6 и омега-3. Рассказываем, чем оно полезно, как отличается от масла CBD и как принимать."},"p":["olio-di-semi-di-canapa-180-softgel"]},{"s":"krill-oil","c":"omega","t":{"uk":"Олія криля: омега-3 у фосфоліпідній формі","ru":"Масло криля: омега-3 в фосфолипидной форме"},"l":{"uk":"Криль — дрібні морські рачки, яких добувають у холодних водах Антарктики. Олія з них містить омега-3, фосфоліпіди та природний пігмент астаксантин. Розповідаємо, чим олія криля відрізняється від риб’ячого жиру та кому вона може підійти.","ru":"Криль — мелкие морские рачки, которых добывают в холодных водах Антарктики. Масло из них содержит омега-3, фосфолипиды и природный пигмент астаксантин. Рассказываем, чем масло криля отличается от рыбьего жира и кому оно может подойти."},"p":["olio-di-krill"]},{"s":"omega3","c":"omega","t":{"uk":"Омега-3: EPA і DHA, навіщо потрібні та як приймати","ru":"Омега-3: EPA и DHA, зачем нужны и как принимать"},"l":{"uk":"Омега-3 жирні кислоти — одні з найвивченіших харчових добавок. Організм не вміє створювати їх у достатній кількості, тому вони мають надходити з їжею. Розповідаємо, чим відрізняються EPA і DHA, кому потрібна добавка та як її правильно приймати.","ru":"Омега-3 жирные кислоты — одни из самых изученных пищевых добавок. Организм не умеет создавать их в достаточном количестве, поэтому они должны поступать с пищей. Рассказываем, чем отличаются EPA и DHA, кому нужна добавка и как её правильно принимать."},"p":["sport-51","sport-omega-180","aldous-omega-3","aldous-omega-3-premium"]},{"s":"ifos","c":"omega","t":{"uk":"Сертифікат IFOS: як перевірити якість риб’ячого жиру","ru":"Сертификат IFOS: как проверить качество рыбьего жира"},"l":{"uk":"Риб’ячий жир — продукт, якість якого складно оцінити на око. Одні капсули містять багато активних кислот і чисті, інші — окиснені або забруднені. Розповідаємо, що означає сертифікат IFOS і чому він важливий під час вибору омега-3.","ru":"Рыбий жир — продукт, качество которого сложно оценить на глаз. Одни капсулы содержат много активных кислот и чисты, другие — окислены или загрязнены. Рассказываем, что означает сертификат IFOS и почему он важен при выборе омега-3."},"p":["sport-51","sport-omega-180"]},{"s":"evening-primrose","c":"women","t":{"uk":"Олія примули вечірньої: GLA для жіночого здоров’я та шкіри","ru":"Масло примулы вечерней: GLA для женского здоровья и кожи"},"l":{"uk":"Примула вечірня — рослина з жовтими квітками, що розкриваються надвечір. Її насіння дає олію, багату на гамма-ліноленову кислоту (GLA). Розповідаємо, чим вона цікава, кому підходить і яких застережних заходів потрібно дотримуватися.","ru":"Примула вечерняя — растение с жёлтыми цветками, раскрывающимися к вечеру. Её семена дают масло, богатое гамма-линоленовой кислотой (GLA). Рассказываем, чем оно интересно, кому подходит и какие предосторожности нужно соблюдать."},"p":["olio-enotera","aldous-olio-di-enotera"]},{"s":"berberine","c":"anti","t":{"uk":"Берберин: рослинна речовина для обміну речовин","ru":"Берберин: растительное вещество для обмена веществ"},"l":{"uk":"Берберин — алкалоїд жовтого кольору, який міститься в барбарисі та деяких інших рослинах. Його використовують у традиційній китайській та аюрведичній практиці вже тисячі років. Розповідаємо, що відомо про берберин, кому він може підійти та чому потрібна обережність.","ru":"Берберин — алкалоид жёлтого цвета, который содержится в барбарисе и некоторых других растениях. Его используют в традиционной китайской и аюрведической практике уже тысячи лет. Рассказываем, что известно о берберине, кому он может подойти и почему необходима осторожность."},"p":["berberina","berberina-120-capsule","berberina-180-compresse","berberina-60-capsule"]},{"s":"raspberry-ketone","c":"weight","t":{"uk":"Малиновий кетон: що відомо та чого очікувати","ru":"Малиновый кетон: что известно и чего ожидать"},"l":{"uk":"Малиновий кетон — ароматична речовина, яка надає запаху малині. Його активно просувають як засіб для схуднення. Розповідаємо чесно, що відомо про малиновий кетон, які в нього обмеження та як використовувати його усвідомлено.","ru":"Малиновый кетон — ароматическое вещество, которое придаёт запах малине. Его активно продвигают как средство для похудения. Рассказываем честно, что известно о малиновом кетоне, какие у него ограничения и как использовать его осознанно."},"p":["chetone-di-lampone-180-compresse"]},{"s":"astaxanthin","c":"anti","t":{"uk":"Астаксантин: потужний каротиноїд із мікроводоростей","ru":"Астаксантин: мощный каротиноид из микроводорослей"},"l":{"uk":"Астаксантин — червоний пігмент, що надає колір лососеві, креветкам і фламінго. Його отримують із мікроводорості гематококус. Це один із найсильніших природних антиоксидантів. Розповідаємо, чим він корисний, кому підходить і як приймати.","ru":"Астаксантин — красный пигмент, который придаёт цвет лососю, креветкам и фламинго. Его получают из микроводоросли гематококкус. Это один из самых сильных природных антиоксидантов. Рассказываем, чем он полезен, кому подходит и как принимать."},"p":["astaxantina-240-compresse","astaxantina-320mg-8-mg-30-capsule","astaxantina-320mg-8-mg-90-capsule","astaxantina-8mg-270-capsule","astaxantina-8mg-90-capsule","aldous-astaxantina"]},{"s":"ginkgo","c":"brain","t":{"uk":"Гінкго білоба: рослина для пам’яті та кровообігу","ru":"Гинкго билоба: растение для памяти и кровообращения"},"l":{"uk":"Гінкго білоба — одне з найстаріших дерев на Землі, яке майже не змінилося за 200 мільйонів років. Екстракт його листя — один із найвивченіших рослинних препаратів для підтримки мозку. Розповідаємо, чим гінкго може бути корисним, як приймати та яких запобіжних заходів дотримуватися.","ru":"Гинкго билоба — одно из старейших деревьев на Земле, которое почти не изменилось за 200 миллионов лет. Экстракт его листьев — один из самых изученных растительных препаратов для поддержки мозга. Рассказываем, чем гинкго может быть полезен, как принимать и каких мер предосторожности придерживаться."},"p":["ginkgo-biloba-365-compresse","aldous-nootropico-con-ginkgo-biloba-criniera-di-leone-caffeina-bacopa-tirosina-teanina-e-huperzia-serrata"]},{"s":"reishi","c":"mush","t":{"uk":"Рейші: гриб безсмертя для спокою та імунітету","ru":"Рейши: гриб бессмертия для спокойствия и иммунитета"},"l":{"uk":"Рейші, або лінчжі, в Азії називають грибом безсмертя. Його використовують уже понад дві тисячі років. Розповідаємо, що відомо про рейші сьогодні, як він може допомогти організму та на що потрібно звернути увагу під час вибору добавки.","ru":"Рейши, или линчжи, в Азии называют грибом бессмертия. Его используют уже более двух тысяч лет. Рассказываем, что известно о рейши сегодня, как он может помочь организму и на что нужно обратить внимание при выборе добавки."},"p":["reishi-150-compresse","reishi-270-compresse"]},{"s":"glucosamine","c":"joint","t":{"uk":"Глюкозамін і хондроїтин: підтримка суглобів","ru":"Глюкозамин и хондроитин: поддержка суставов"},"l":{"uk":"Глюкозамін і хондроїтин — одні з найвідоміших добавок для суглобів. Вони входять до складу хрящової тканини. Розповідаємо, що відомо про їхню дію, кому вони підходять і як приймати їх правильно.","ru":"Глюкозамин и хондроитин — одни из самых известных добавок для суставов. Они входят в состав хрящевой ткани. Рассказываем, что известно об их действии, кому они подходят и как принимать их правильно."},"p":["glucosamina-366-compresse","aldous-glucosamina-condroitina-msm-vitamine-e-minerali"]},{"s":"msm","c":"joint","t":{"uk":"МСМ (метилсульфонілметан): органічна сірка для суглобів і шкіри","ru":"МСМ (метилсульфонилметан): органическая сера для суставов и кожи"},"l":{"uk":"МСМ — природна сірковмісна сполука, яка трапляється в невеликих кількостях у їжі та в організмі. Її використовують як добавку для суглобів, шкіри та волосся. Розповідаємо, що відомо про МСМ, для кого він підходить і як приймати.","ru":"МСМ — природное серосодержащее соединение, которое встречается в небольших количествах в пище и в организме. Его используют как добавку для суставов, кожи и волос. Рассказываем, что известно о МСМ, для кого он подходит и как принимать."},"p":["msm","msm-365-compresse","aldous-glucosamina-condroitina-msm-vitamine-e-minerali"]},{"s":"nad","c":"anti","t":{"uk":"NAD+ і нікотинамід рибозид: клітинна енергія","ru":"NAD+ и никотинамид рибозид: клеточная энергия"},"l":{"uk":"NAD+ — молекула, без якої не працює жодна клітина. З віком її рівень знижується, тому попередники NAD+ привертають увагу вчених. Розповідаємо, що таке NAD+, чим відрізняються нікотинамід рибозид і ліпосомальний NAD та що відомо про їхню дію.","ru":"NAD+ — молекула, без которой не работает ни одна клетка. С возрастом её уровень снижается, поэтому предшественники NAD+ привлекают внимание учёных. Рассказываем, что такое NAD+, чем отличаются никотинамид рибозид и липосомальный NAD и что известно об их действии."},"p":["nad-liposomiale-120-capsule","nad-nicotinamide-riboside-cloruro-300mg-90-capsule","aldous-nad-con-resveratrolo-e-coenzima-q10"]},{"s":"ashwagandha","c":"herb","t":{"uk":"Ашваганда: адаптоген для стресу та сну","ru":"Ашваганда: адаптоген для стресса и сна"},"l":{"uk":"Ашваганда, або індійський женьшень, — одна з найвідоміших рослин аюрведи. Її корінь століттями використовують для підтримки сил і спокою. Розповідаємо, що відомо про ашвагандху сьогодні, кому вона може підійти та які запобіжні заходи важливі.","ru":"Ашваганда, или индийский женьшень, — одно из самых известных растений аюрведы. Её корень веками используют для поддержки сил и спокойствия. Рассказываем, что известно об ашвагандхе сегодня, кому она может подойти и какие меры предосторожности важны."},"p":["ashwagandha-180-compresse","ashwagandha-bio-180-capsule","ashwagandha-complex-60-capsule","ashwagandha","aldous-ashwagandha-caramelle-gommose","aldous-ashwagandha-ksm-66-biologica","aldous-ashwagandha-con-pepe-nero-biologico"]},{"s":"lions-mane","c":"mush","t":{"uk":"Левова грива: гриб для ясності розуму та фокуса","ru":"Львиная грива: гриб для ясности ума и фокуса"},"l":{"uk":"Левова грива, або їжовик гребінчастий, зовні схожий на пухнасту білу кулю. В Азії його здавна використовували в харчуванні та традиційній практиці. Сьогодні його вивчають як рослину для підтримки концентрації та нервової системи. Розбираємося, що відомо про нього.","ru":"Львиная грива, или ежовик гребенчатый, внешне похож на пушистый белый шар. В Азии его издавна использовали в питании и традиционной практике. Сегодня его изучают как растение для поддержки концентрации и нервной системы. Разбираемся, что известно о нём."},"p":["lions-mane-365-compresse","aldous-nootropico-con-ginkgo-biloba-criniera-di-leone-caffeina-bacopa-tirosina-teanina-e-huperzia-serrata"]},{"s":"chaga","c":"mush","t":{"uk":"Чага: березовий гриб та його властивості","ru":"Чага: берёзовый гриб и его свойства"},"l":{"uk":"Чага — темний наріст на березі, який у народній практиці Росії, Скандинавії та Сибіру використовували як настій, що нагадує чай. Сьогодні його вивчають як джерело антиоксидантів. Розповідаємо, чим чага цікава та які в неї є обмеження.","ru":"Чага — тёмный нарост на берёзе, который в народной практике России, Скандинавии и Сибири использовали как настой, напоминающий чай. Сегодня его изучают как источник антиоксидантов. Рассказываем, чем чага интересна и какие у неё есть ограничения."},"p":["chaga-366-compresse"]},{"s":"agaricus-blazei","c":"mush","t":{"uk":"Агарикус Блазеї (ABM): бразильський гриб для імунітету","ru":"Агарикус Блазеи (ABM): бразильский гриб для иммунитета"},"l":{"uk":"Агарикус Блазеї, або «гриб сонця», родом із Бразилії, де місцеві жителі здавна вживали його в їжу. Сьогодні його вивчають як джерело бета-глюканів. Розповідаємо, що це за гриб, чим він цікавий і яких запобіжних заходів потрібно дотримуватися.","ru":"Агарикус Блазеи, или «гриб солнца», родом из Бразилии, где местные жители издавна употребляли его в пищу. Сегодня его изучают как источник бета-глюканов. Рассказываем, что это за гриб, чем он интересен и какие меры предосторожности нужно соблюдать."},"p":["agaricus-blazei-abm-120-capsule"]},{"s":"maitake","c":"mush","t":{"uk":"Майтаке: гриб-танцюрист та його особливості","ru":"Майтаке: гриб-танцор и его особенности"},"l":{"uk":"Майтаке, або «танцюючий гриб», в Японії вважали настільки цінним, що знахідка його в лісі була приводом для радості. Розповідаємо, чим цей гриб цікавий, що таке D-фракція та як приймати майтаке у вигляді добавки.","ru":"Майтаке, или «танцующий гриб», в Японии считали настолько ценным, что находка его в лесу была поводом для радости. Рассказываем, чем этот гриб интересен, что такое D-фракция и как принимать майтаке в виде добавки."},"p":["maitake-120-capsule"]},{"s":"cordyceps","c":"mush","t":{"uk":"Кордицепс: гриб витривалості та енергії","ru":"Кордицепс: гриб выносливости и энергии"},"l":{"uk":"Кордицепс у традиційній китайській і тибетській практиці використовували для сили та витривалості. Розповідаємо, чим кордицепс цікавий спортсменам і всім, хто хоче підтримати енергію, як він виходить і як приймати добавку.","ru":"Кордицепс в традиционной китайской и тибетской практике использовали для силы и выносливости. Рассказываем, чем кордицепс интересен спортсменам и всем, кто хочет поддержать энергию, как он получается и как принимать добавку."},"p":["cordyceps-sinensis-120-capsule","cordyceps-sinensis-270-capsule"]},{"s":"milk-thistle","c":"herb","t":{"uk":"Розторопша: рослина для підтримки печінки","ru":"Расторопша: растение для поддержки печени"},"l":{"uk":"Розторопша плямиста — одна з найвідоміших рослин для турботи про печінку. Її використовують уже понад дві тисячі років. Розповідаємо, що таке силімарин, кому підходить розторопша та як приймати її безпечно.","ru":"Расторопша пятнистая — одно из самых известных растений для заботы о печени. Её используют уже более двух тысяч лет. Рассказываем, что такое силимарин, кому подходит расторопша и как принимать её безопасно."},"p":["cardo-mariano","cardo-mariano-366-compresse","aldous-cardo-mariano-con-carciofo-curcuma-tarassaco-e-desmodio","yamamoto-sily-caps-60-capsule","yamamoto-blackguardian-60-compresse"]},{"s":"melatonin","c":"brain","t":{"uk":"Мелатонін: гормон сну та як його приймати","ru":"Мелатонин: гормон сна и как его принимать"},"l":{"uk":"Мелатонін — гормон, який виробляється в шишкоподібній залозі в темряві та повідомляє організму, що пора спати. Він допомагає регулювати циркадні ритми. Розповідаємо, коли мелатонін може допомогти, як приймати його правильно та які є обмеження.","ru":"Мелатонин — гормон, который вырабатывается в шишковидной железе в темноте и сообщает организму, что пора спать. Он помогает регулировать циркадные ритмы. Рассказываем, когда мелатонин может помочь, как принимать его правильно и какие есть ограничения."},"p":["melatonina-200-compresse","melatonina-400-compresse","aldous-triptofano-con-melatonina-magnesio-spirulina-e-vitamine","aldous-melatonina-caramelle-gommose","aldous-melatonina-pura","aldous-melatonina-in-gocce"]},{"s":"coq10","c":"anti","t":{"uk":"Коензим Q10: енергія для серця та клітин","ru":"Коэнзим Q10: энергия для сердца и клеток"},"l":{"uk":"Коензим Q10 — речовина, яка виробляється в організмі та бере участь в отриманні енергії в клітинах. Найбільше його в серці, печінці та нирках. Розповідаємо, навіщо потрібен Q10, як його рівень пов’язаний із віком і прийомом статинів та як приймати добавку.","ru":"Коэнзим Q10 — вещество, которое вырабатывается в организме и участвует в получении энергии в клетках. Больше всего его в сердце, печени и почках. Рассказываем, зачем нужен Q10, как его уровень связан с возрастом и приёмом статинов и как принимать добавку."},"p":["coenzima-q-10-120-capsule","coenzima-q-10-60-capsule","aldous-vitamina-c-con-zinco-e-coenzima-q10","aldous-collagene-idrolizzato-con-acido-ialuronico-coenzima-q10-zinco-e-vitamine","aldous-coenzima-q10","aldous-riso-rosso-fermentato-con-coenzima-q10"]},{"s":"cavaq10","c":"anti","t":{"uk":"Коензим Q10 з покращеним засвоєнням: комплекс із гамма-циклодекстрином","ru":"Коэнзим Q10 с улучшенным усвоением: комплекс с гамма-циклодекстрином"},"l":{"uk":"Головна проблема коензиму Q10 — погане засвоєння: він жиророзчинний і погано розчиняється у воді. Тому створюють спеціальні форми. Розповідаємо про комплекс Q10 із гамма-циклодекстрином, чим він відрізняється від звичайних форм і кому підходить.","ru":"Главная проблема коэнзима Q10 — плохое усвоение: он жирорастворим и плохо растворяется в воде. Поэтому создают специальные формы. Рассказываем о комплексе Q10 с гамма-циклодекстрином, чем он отличается от обычных форм и кому подходит."},"p":["coenzima-q-10-120-capsule","coenzima-q-10-60-capsule"]},{"s":"nac","c":"anti","t":{"uk":"NAC (N-ацетилцистеїн): попередник глутатіону","ru":"NAC (N-ацетилцистеин): предшественник глутатиона"},"l":{"uk":"NAC — форма амінокислоти цистеїну, яку використовують уже кілька десятиліть. Вона потрібна організму для утворення глутатіону — головного внутрішньоклітинного антиоксиданту. Розповідаємо, чим корисний NAC, кому він підходить і як приймати.","ru":"NAC — форма аминокислоты цистеина, которую используют уже несколько десятилетий. Она нужна организму для образования глутатиона — главного внутриклеточного антиоксиданта. Рассказываем, чем полезен NAC, кому он подходит и как принимать."},"p":["nac","nac-600mg-220-capsule","nac-800mg-220-capsule","aldous-nac-integratore-selenio-vitamina-e","yamamoto-blackguardian-60-compresse"]},{"s":"tryptophan","c":"brain","t":{"uk":"L-триптофан: амінокислота для сну та настрою","ru":"L-триптофан: аминокислота для сна и настроения"},"l":{"uk":"L-триптофан — незамінна амінокислота, яка має надходити з їжею. З неї організм виробляє серотонін і мелатонін — речовини, пов’язані з настроєм і сном. Розповідаємо, чим корисний триптофан, кому він підходить і які в нього є обмеження.","ru":"L-триптофан — незаменимая аминокислота, которая должна поступать с пищей. Из неё организм вырабатывает серотонин и мелатонин — вещества, связанные с настроением и сном. Рассказываем, чем полезен триптофан, кому он подходит и какие у него есть ограничения."},"p":["l-triptofano-240-capsule","aldous-triptofano-con-melatonina-magnesio-spirulina-e-vitamine","aldous-triptofano-puro"]},{"s":"glucomannan","c":"weight","t":{"uk":"Глюкоманнан: клітковина з кореня конжаку для контролю ваги","ru":"Глюкоманнан: клетчатка из корня конжака для контроля веса"},"l":{"uk":"Глюкоманнан — розчинне харчове волокно з кореня конжаку, яке здатне вбирати воду й збільшуватися в об’ємі в десятки разів. Це одна з небагатьох добавок для контролю ваги, ефект якої визнано європейськими експертами. Розповідаємо, як вона працює та як приймати безпечно.","ru":"Глюкоманнан — растворимое пищевое волокно из корня конжака, которое способно впитывать воду и увеличиваться в объёме в десятки раз. Это одна из немногих добавок для контроля веса, эффект которой признан европейскими экспертами. Рассказываем, как она работает и как принимать безопасно."},"p":["glucomannano-240-capsule"]},{"s":"forskolin","c":"weight","t":{"uk":"Форсколін: екстракт колеуса для обміну речовин","ru":"Форсколин: экстракт колеуса для обмена веществ"},"l":{"uk":"Форсколін — речовина з кореня колеуса форсколії, рослини, яка використовується в аюрведі. Його включають у комплекси для контролю ваги та підтримки обміну речовин. Розповідаємо, як він діє, що відомо про ефективність і які потрібні запобіжні заходи.","ru":"Форсколин — вещество из корня колеуса форсколии, растения, которое используется в аюрведе. Его включают в комплексы для контроля веса и поддержки обмена веществ. Рассказываем, как он действует, что известно об эффективности и какие нужны меры предосторожности."},"p":["forskolina-60-capsule"]},{"s":"gaba","c":"brain","t":{"uk":"ГАМК (GABA): амінокислота для розслаблення","ru":"ГАМК (GABA): аминокислота для расслабления"},"l":{"uk":"ГАМК — головний гальмівний нейромедіатор мозку: вона допомагає нервовій системі «заспокоюватися». Добавки ГАМК популярні для розслаблення та сну. Розповідаємо, що відомо про її дію, кому вона може підійти та чому дані неоднозначні.","ru":"ГАМК — главный тормозной нейромедиатор мозга: она помогает нервной системе «успокаиваться». Добавки ГАМК популярны для расслабления и сна. Рассказываем, что известно о её действии, кому она может подойти и почему данные неоднозначны."},"p":["gaba"]},{"s":"ala","c":"anti","t":{"uk":"Альфа-ліпоєва кислота: універсальний антиоксидант","ru":"Альфа-липоевая кислота: универсальный антиоксидант"},"l":{"uk":"Альфа-ліпоєва кислота (АЛК) — речовина, яка виробляється в організмі та бере участь в отриманні енергії. Вона розчиняється і у воді, і в жирах, тому захищає клітини в різних середовищах. Розповідаємо, чим корисна АЛК, кому підходить і як приймати.","ru":"Альфа-липоевая кислота (АЛК) — вещество, которое вырабатывается в организме и участвует в получении энергии. Она растворяется и в воде, и в жирах, поэтому защищает клетки в разных средах. Рассказываем, чем полезна АЛК, кому подходит и как принимать."},"p":["acido-alfa-lipoico","acido-alfa-lipoico-120-capsule"]},{"s":"apple-vinegar","c":"gut","t":{"uk":"Яблучний оцет у капсулах: що відомо про користь","ru":"Яблочный уксус в капсулах: что известно о пользе"},"l":{"uk":"Яблучний оцет став одним із найпопулярніших «народних» засобів для травлення та контролю ваги. Розповідаємо, що справді відомо про його вплив, чим зручні капсули порівняно з рідким оцтом і яких запобіжних заходів потрібно дотримуватися.","ru":"Яблочный уксус стал одним из самых популярных «народных» средств для пищеварения и контроля веса. Рассказываем, что действительно известно о его влиянии, чем удобны капсулы по сравнению с жидким уксусом и какие меры предосторожности нужно соблюдать."},"p":["aceto-di-sidro-di-mele-180-capsule","aldous-aceto-di-mele-in-gommose"]},{"s":"glutathione","c":"anti","t":{"uk":"Глутатіон: головний антиоксидант клітини","ru":"Глутатион: главный антиоксидант клетки"},"l":{"uk":"Глутатіон називають «майстер-антиоксидантом»: він є в кожній клітині та бере участь у захисті від вільних радикалів і в знешкодженні токсинів. Розповідаємо, що таке глутатіон, чи можна підвищити його рівень за допомогою добавок і як це роблять.","ru":"Глутатион называют «мастер-антиоксидантом»: он есть в каждой клетке и участвует в защите от свободных радикалов и в обезвреживании токсинов. Рассказываем, что такое глутатион, можно ли повысить его уровень с помощью добавок и как это делают."},"p":["glutatione"]},{"s":"red-yeast-rice","c":"anti","t":{"uk":"Червоний ферментований рис і холестерин","ru":"Красный ферментированный рис и холестерин"},"l":{"uk":"Червоний ферментований рис — продукт традиційної китайської кухні, який отримують за вирощування пліснявого гриба на рисі. Він містить монаколін K, який пов’язаний із підтриманням нормального рівня холестерину. Розповідаємо, як він діє та чому потрібна обережність.","ru":"Красный ферментированный рис — продукт традиционной китайской кухни, который получают при выращивании плесневого гриба на рисе. Он содержит монаколин K, который связан с поддержанием нормального уровня холестерина. Рассказываем, как он действует и почему нужна осторожность."},"p":["riso-rosso-fermentato-180-compresse","riso-rosso-fermentato-90-compresse","aldous-riso-rosso-fermentato-con-coenzima-q10"]},{"s":"bromelain","c":"gut","t":{"uk":"Бромелайн: ферменти ананаса для травлення та комфорту","ru":"Бромелайн: ферменты ананаса для пищеварения и комфорта"},"l":{"uk":"Бромелайн — суміш ферментів, що розщеплюють білки, яку отримують зі стебла ананаса. Його застосовують для підтримки травлення, а також для комфорту тканин після навантажень і втручань. Розповідаємо, як він діє, кому підходить і як приймати.","ru":"Бромелайн — смесь ферментов, расщепляющих белки, которую получают из стебля ананаса. Его применяют для поддержки пищеварения, а также для комфорта тканей после нагрузок и вмешательств. Рассказываем, как он действует, кому подходит и как принимать."},"p":["bromelina","bromelina-200-compresse"]},{"s":"lactoferrin","c":"anti","t":{"uk":"Лактоферин: білок молока для імунітету","ru":"Лактоферрин: белок молока для иммунитета"},"l":{"uk":"Лактоферин — білок, який міститься в молоці, слізній рідині, слині та інших рідинах організму. Він бере участь у захисті від мікроорганізмів і в обміні заліза. Розповідаємо, що відомо про лактоферин, кому він може підійти й як приймати.","ru":"Лактоферрин — белок, который содержится в молоке, слезах, слюне и других жидкостях организма. Он участвует в защите от микроорганизмов и в обмене железа. Рассказываем, что известно о лактоферрине, кому он может подойти и как принимать."},"p":["lattoferrina-30-capsule","lattoferrina-60-capsule"]},{"s":"curcuma","c":"herb","t":{"uk":"Куркума й куркумін: користь і засвоєння","ru":"Куркума и куркумин: польза и усвоение"},"l":{"uk":"Куркума — не лише спеція жовтого кольору, а й один із найдослідженіших рослинних інгредієнтів. Її головна речовина, куркумін, привертає увагу вчених антиоксидантними властивостями. Розбираємо, навіщо приймати куркуму та як зробити так, щоб вона засвоювалася.","ru":"Куркума — не только пряность жёлтого цвета, но и один из самых изученных растительных ингредиентов. Её главное вещество, куркумин, привлекает внимание учёных своими антиоксидантными свойствами. Разбираем, зачем принимать куркуму и как сделать так, чтобы она усваивалась."},"p":["curcuma","aldous-curcuma-biologica-con-zenzero-pepe-nero-e-probiotici","aldous-curcuma-caramelle-gommose"]},{"s":"grape-seed","c":"herb","t":{"uk":"Екстракт кісточок винограду (OPC): антиоксидант для судин","ru":"Экстракт косточек винограда (OPC): антиоксидант для сосудов"},"l":{"uk":"Кісточки винограду — те, що ми зазвичай викидаємо, — виявляються багатим джерелом проантоціанідинів. Ці речовини давно вивчаються як природні антиоксиданти. Розповідаємо, що таке OPC, чим він може бути корисним і як його приймати.","ru":"Косточки винограда — то, что мы обычно выбрасываем, — оказываются богатым источником проантоцианидинов. Эти вещества давно изучаются как природные антиоксиданты. Рассказываем, что такое OPC, чем он может быть полезен и как его принимать."},"p":["opc","opc-estratto-di-semi-duva"]},{"s":"d-mannose","c":"gut","t":{"uk":"D-маноза: підтримка сечовивідних шляхів","ru":"D-манноза: поддержка мочевыводящих путей"},"l":{"uk":"D-маноза — простий цукор, що міститься в журавлині, персиках, яблуках і деяких інших рослинах. Її використовують для підтримки здоров’я сечовивідних шляхів. Розповідаємо, як вона діє, кому підходить і чому важливо не відкладати візит до лікаря.","ru":"D-манноза — простой сахар, который содержится в клюкве, персиках, яблоках и некоторых других растениях. Её используют для поддержки здоровья мочевыводящих путей. Рассказываем, как она действует, кому подходит и почему важно не откладывать визит к врачу."},"p":["d-mannosio","d-mannosio-180-capsule"]},{"s":"maca","c":"herb","t":{"uk":"Мака перуанська: енергія, лібідо та гормональний баланс","ru":"Мака перуанская: энергия, либидо и гормональный баланс"},"l":{"uk":"Мака — коренеплід, що росте високо в Андах і століттями використовувався мешканцями Перу для витривалості й енергії. Сьогодні її приймають у вигляді порошку та капсул. Розповідаємо, чим мака може бути корисною, кому підходить і як її правильно приймати.","ru":"Мака — корнеплод, который растёт высоко в Андах и веками использовался жителями Перу для выносливости и энергии. Сегодня её принимают в виде порошка и капсул. Рассказываем, чем мака может быть полезна, кому подходит и как её правильно принимать."},"p":["maca-power-240-capsule","maca","aldous-maca-andina","aldous-maca-nera"]},{"s":"moringa","c":"herb","t":{"uk":"Моринга олейфера: дерево життя та його листя","ru":"Моринга олейфера: дерево жизни и его листья"},"l":{"uk":"Морингу називають деревом життя за багатий склад листя. Воно містить вітаміни, мінерали, білок і рослинні антиоксиданти. Розбираємося, чим моринга може бути корисною, кому підходить і як її приймати.","ru":"Моринга называют деревом жизни за богатый состав листьев. Они содержат витамины, минералы, белок и растительные антиоксиданты. Разбираемся, чем моринга может быть полезна, кому подходит и как её принимать."},"p":["moringa-oleifera-90-capsule","aldous-moringa-biologica"]},{"s":"shilajit","c":"herb","t":{"uk":"Шиладжит (мумійо): природна смола гір","ru":"Шиладжит (мумиё): природная смола гор"},"l":{"uk":"Шиладжит — темна смолиста маса, що виступає з гірських порід у Гімалаях, на Алтаї та в інших горах. В аюрведі його використовують уже тисячі років. Розповідаємо, що це таке, чим може бути цікавий і як не помилитися під час вибору.","ru":"Шиладжит — тёмная смолистая масса, которая выступает из горных пород в Гималаях, на Алтае и в других горах. В аюрведе его используют уже тысячи лет. Рассказываем, что это такое, чем может быть интересен и как не ошибиться при выборе."},"p":["shilajit-120-capsule"]},{"s":"polydatin","c":"herb","t":{"uk":"Полідатин: родич ресвератролу","ru":"Полидатин: родственник ресвератрола"},"l":{"uk":"Полідатин — природна речовина з рослини горець японський, споріднена зі знаменитим ресвератролом. Його вивчають як антиоксидант із доброю засвоюваністю. Розповідаємо, що це таке, для чого його приймають і які нюанси потрібно врахувати.","ru":"Полидатин — природное вещество из растения горец японский, родственное знаменитому ресвератролу. Его изучают как антиоксидант с хорошей усвояемостью. Рассказываем, что это такое, для чего его принимают и какие нюансы нужно учесть."},"p":["polidatina-90-capsule","aldous-resveratrolo-con-vitamina-c"]},{"s":"serenoa","c":"herb","t":{"uk":"Серенойя повзуча: підтримка здоров’я простати","ru":"Серенойя ползучая: поддержка здоровья простаты"},"l":{"uk":"Серенойя повзуча, або сабаль, — пальма з південного сходу США, плоди якої здавна використовують для підтримки чоловічого здоров’я. Розповідаємо, що відомо про екстракт, кому він підходить і чому важливо спершу звернутися до лікаря.","ru":"Серенойя ползучая, или сабаль, — пальма из юго-востока США, плоды которой издавна используют для поддержки мужского здоровья. Рассказываем, что известно об экстракте, кому он подходит и почему важно сначала обратиться к врачу."},"p":["euprost-serenoa-repens-180-capsule"]},{"s":"cimicifuga","c":"women","t":{"uk":"Цимицифуга (чорний кохош, клопогон): рослинна підтримка в менопаузі","ru":"Цимицифуга (чёрный кохош, клопогон): растительная поддержка в менопаузе"},"l":{"uk":"Цимицифуга кистевидна, або клопогон, — багаторічна рослина Північної Америки, кореневища якої здавна застосовують жінки в період менопаузи. Розповідаємо, що відомо про екстракт цимицифуги, для кого він може підійти та які потрібні запобіжні заходи.","ru":"Цимицифуга кистевидная, или клопогон, — многолетнее растение Северной Америки, корневища которого давно применяют женщины в период менопаузы. Рассказываем, что известно об экстракте цимицифуги, для кого он может подойти и какие нужны меры предосторожности."},"p":["cimicifuga-300-compresse","philautia-3"]},{"s":"lactase","c":"gut","t":{"uk":"Лактаза: що робити за непереносимості лактози","ru":"Лактаза: что делать при непереносимости лактозы"},"l":{"uk":"Непереносимість лактози — одна з найчастіших причин дискомфорту після молочних продуктів. Причина в нестачі ферменту лактази. Розповідаємо, як проявляється непереносимість, чим вона відрізняється від алергії та як допомагає добавка з лактазою.","ru":"Непереносимость лактозы — одна из самых частых причин дискомфорта после молочных продуктов. Причина в нехватке фермента лактазы. Рассказываем, как проявляется непереносимость, чем она отличается от аллергии и как помогает добавка с лактазой."},"p":["lattasi"]},{"s":"probiotic","c":"gut","t":{"uk":"Пробіотики: корисні бактерії для кишечника","ru":"Пробиотики: полезные бактерии для кишечника"},"l":{"uk":"Пробіотики — це живі мікроорганізми, які за прийому в достатній кількості можуть приносити користь організму. Вони підтримують баланс кишкової мікрофлори. Розповідаємо, як вони працюють, кому можуть бути корисні й як приймати їх правильно.","ru":"Пробиотики — это живые микроорганизмы, которые при приёме в достаточном количестве могут приносить пользу организму. Они поддерживают баланс кишечной микрофлоры. Рассказываем, как они работают, кому могут быть полезны и как принимать их правильно."},"p":["florax-60-capsule","aldous-probiotici-con-vitamine-nelle-caramelle-gommose","aldous-probiotici-per-bambini-caramelle-gommose"]},{"s":"microbiota","c":"gut","t":{"uk":"Мікробіота кишечника: як підтримувати баланс","ru":"Микробиота кишечника: как поддерживать баланс"},"l":{"uk":"У нашому кишечнику живуть трильйони мікроорганізмів, які разом називають мікробіотою. Вони беруть участь у травленні, роботі імунної системи й навіть впливають на настрій. Розповідаємо, що таке мікробіота, від чого залежить її стан і як про неї дбати.","ru":"В нашем кишечнике живут триллионы микроорганизмов, которые вместе называют микробиотой. Они участвуют в пищеварении, работе иммунной системы и даже влияют на настроение. Рассказываем, что такое микробиота, от чего зависит её состояние и как о ней заботиться."},"p":["florax-60-capsule","aldous-probiotici-con-vitamine-nelle-caramelle-gommose","aldous-probiotici-per-bambini-caramelle-gommose"]},{"s":"detox","c":"gut","t":{"uk":"Детокс: як м’яко підтримати природне очищення організму","ru":"Детокс: как мягко поддержать естественное очищение организма"},"l":{"uk":"Слово «детокс» часто обіцяє забагато. Насправді організм постійно очищається сам, і жодна добавка не може «вивести всі токсини». Розповідаємо, як працює природна система очищення, що можна зробити для її підтримки та на що звертати увагу в добавках.","ru":"Слово «детокс» часто обещает слишком много. На самом деле организм постоянно очищается сам, и никакая добавка не может «вывести все токсины». Рассказываем, как работает естественная система очищения, что можно сделать для её поддержки и на что обращать внимание в добавках."},"p":["detox-capsule","detox-liquido","aldous-clorella-biologica","aldous-mix-di-spirulina-e-clorella-biologica","aldous-spirulina-biologica"]},{"s":"citicoline","c":"brain","t":{"uk":"Цитиколін (CDP-холін): підтримка пам’яті та уваги","ru":"Цитиколин (CDP-холин): поддержка памяти и внимания"},"l":{"uk":"Цитиколін — природна речовина, яка утворюється в організмі з холіну та цитидину. Вона бере участь у побудові мембран нервових клітин і у виробленні нейромедіаторів. Розповідаємо, чим може бути корисний цитиколін, кому він підходить і як приймати.","ru":"Цитиколин — природное вещество, которое образуется в организме из холина и цитидина. Оно участвует в построении мембран нервных клеток и в выработке нейромедиаторов. Рассказываем, чем может быть полезен цитиколин, кому он подходит и как принимать."},"p":["citicolina-125-compresse"]},{"s":"how-to-take","c":"guide","t":{"uk":"Як і коли приймати добавки: прості правила","ru":"Как и когда принимать добавки: простые правила"},"l":{"uk":"Ефект від добавок значною мірою залежить від того, коли та з чим їх приймати. Одні речовини краще засвоюються з їжею, інші — натщесерце, деякі конфліктують одна з одною. Зібрали прості й зрозумілі правила, які допоможуть отримати від добавок максимум користі та уникнути помилок.","ru":"Эффект от добавок во многом зависит от того, когда и с чем их принимать. Одни вещества лучше усваиваются с едой, другие — натощак, некоторые конфликтуют друг с другом. Собрали простые и понятные правила, которые помогут получить от добавок максимум пользы и избежать ошибок."},"p":["multivitaminico"]},{"s":"liposomal","c":"guide","t":{"uk":"Ліпосомальні добавки: що це таке та чим вони відрізняються","ru":"Липосомальные добавки: что это такое и чем они отличаются"},"l":{"uk":"Ліпосомальні добавки з’явилися порівняно нещодавно, і навколо них багато запитань. Що таке ліпосоми, чи справді такі добавки засвоюються краще та кому вони підходять? Розбираємо спокійно й без рекламних обіцянок.","ru":"Липосомальные добавки появились сравнительно недавно, и вокруг них много вопросов. Что такое липосомы, действительно ли такие добавки усваиваются лучше и кому они подходят? Разбираем спокойно и без рекламных обещаний."},"p":["nad-liposomiale-120-capsule"]},{"s":"potassium","c":"min","t":{"uk":"Калій: роль в організмі, джерела та добавки","ru":"Калий: роль в организме, источники и добавки"},"l":{"uk":"Калій — мінерал, який потрібен нервам, м’язам і серцю. Він бере участь у водно-сольовому обміні та підтриманні нормального артеріального тиску. Розбираємо, де брати калій, коли добавка має сенс і чому з нею потрібна обережність.","ru":"Калий — минерал, который нужен нервам, мышцам и сердцу. Он участвует в водно-солевом обмене и поддержании нормального артериального давления. Разбираем, где брать калий, когда добавка имеет смысл и почему с ней нужна осторожность."},"p":["aldous-potassio-con-vitamina-c"]},{"s":"inositol","c":"women","t":{"uk":"Інозитол: міо- і D-хіро-інозитол — що це і для кого","ru":"Инозитол: мио- и D-хиро-инозитол — что это и для кого"},"l":{"uk":"Інозитол — вітаміноподібна речовина, яку організм виробляє сам і отримує з їжею. У добавках найчастіше зустрічаються дві його форми: міо- та D-хіро-інозитол. Розбираємо, навіщо їх приймають, як дозують і на що звернути увагу.","ru":"Инозитол — витаминоподобное вещество, которое организм вырабатывает сам и получает с пищей. В добавках чаще всего встречаются две его формы: мио- и D-хиро-инозитол. Разбираем, зачем их принимают, как дозируют и на что обратить внимание."},"p":["aldous-inositolo"]},{"s":"oregano-oil","c":"anti","t":{"uk":"Олія орегано і карвакрол: що відомо про цю добавку","ru":"Масло орегано и карвакрол: что известно об этой добавке"},"l":{"uk":"Олія орегано — концентрований екстракт рослини Origanum vulgare, головний активний компонент якого — карвакрол. Його багато вивчають у лабораторіях, але даних про ефекти в людей поки небагато. Розповідаємо, що відомо, а що — лише припущення.","ru":"Масло орегано — концентрированный экстракт растения Origanum vulgare, главный активный компонент которого — карвакрол. Его много изучают в лабораториях, но данных об эффектах у людей пока немного. Рассказываем, что известно, а что — только предположения."},"p":["aldous-olio-di-origano"]},{"s":"herbal-drainage","c":"gut","t":{"uk":"Дренажні трави: кульбаба, мучниця, золотушник та інші","ru":"Дренажные травы: одуванчик, толокнянка, золотарник и другие"},"l":{"uk":"Комплекси для «дренажу» поєднують рослини, які традиційно використовують для підтримки виведення зайвої рідини та очищувальних функцій організму. Розбираємо, що зазвичай входить у такі формули, як їх приймати і коли потрібна обережність.","ru":"Комплексы для «дренажа» объединяют растения, которые традиционно используют для поддержки выведения лишней жидкости и очищающих функций организма. Разбираем, что обычно входит в такие формулы, как их принимать и когда нужна осторожность."},"p":["yamamoto-ai-diurebol-150-capsule"]},{"s":"thermogenics","c":"weight","t":{"uk":"Термогенні добавки: як працюють і чим ризикують","ru":"Термогенные добавки: как работают и чем рискуют"},"l":{"uk":"Термогенні добавки поєднують кофеїн і рослинні екстракти, щоб підтримати енергію та обмін речовин у межах дієти й тренувань. Розбираємо, з чого вони складаються, чого від них реально чекати і кому вони не підходять.","ru":"Термогенные добавки сочетают кофеин и растительные экстракты, чтобы поддержать энергию и обмен веществ в рамках диеты и тренировок. Разбираем, из чего они состоят, чего от них реально ждать и кому они не подходят."},"p":["yamamoto-ai-burn-180-capsule","yamamoto-ai-burn-hardcore-180-capsule","yamamoto-termoned-30-compresse"]}];